package dev.zomboidmelee.boxing;
import net.minecraft.network.RegistryFriendlyByteBuf;import net.neoforged.neoforge.network.handling.IPayloadHandler;import java.util.concurrent.*;
public class ProtocolChecks18{public static class Registrar{public IPayloadHandler<Heavy18>handler;public Object type,codec;public Registrar playBidirectional(Object t,Object c,IPayloadHandler<Heavy18> h){return playToServer(t,c,h);}public Registrar playToServer(Object type,Object codec,IPayloadHandler<Heavy18> h){this.type=type;this.codec=codec;handler=h;return this;}}public static class Register{Registrar r=new Registrar();public Registrar registrar(String v){return r;}}public static class Context{public Runnable task;CombatChecks18.Actor p=new CombatChecks18.Actor();public Object player(){return p;}public CompletableFuture<Void>enqueueWork(Runnable r){task=r;return CompletableFuture.completedFuture(null);}}
 public static void main(String[]args){for(int id:new int[]{-1,0,1,128,Integer.MAX_VALUE})for(int action:new int[]{0,1}){RegistryFriendlyByteBuf b=new RegistryFriendlyByteBuf();Heavy18 p=new Heavy18(id,action);Heavy18.CODEC.encode(b,p);if(!p.equals(Heavy18.CODEC.decode(b)))throw new AssertionError("payload roundtrip");}Register e=new Register();Combat18.register(e);if(e.r.type!=Heavy18.TYPE||e.r.codec!=Heavy18.CODEC)throw new AssertionError("server registration");Context c=new Context();e.r.handler.handle(new Heavy18(-1,0),c);if(c.task==null||Combat18.NEXT.containsKey(c.p))throw new AssertionError("network thread cannot mutate world");c.task.run();if(Combat18.NEXT.get(c.p)!=118||c.p.w.sounds!=1)throw new AssertionError("queued server action");Combat18.send(45,1);if(!new Heavy18(45,1).equals(net.neoforged.neoforge.network.PacketDistributor.sent))throw new AssertionError("client sends requested action");Combat18.request(c.p,-1,999);if(c.p.w.sounds!=1)throw new AssertionError("invalid action ignored");System.out.println("HEAVY_STOMP_PAYLOAD_ROUNDTRIP_SERVER_QUEUE_REGISTRATION_SEND_CHECKS=15");}
}
